# Define the check function to see if g(x) is its own inverse for given a
def check_inverse(a):
    # We'll check for a range of x values to ensure g(g(x)) == x
    for x in range(-10, 11):
        if g(g(x, a), a) != x:
            return False
    return True

# Check which value of a makes g(x) identical to its inverse
for a in range(-10, 11):
    if check_inverse(a):
        result = a
        break

print(result)
